% 自編 Gauss-Seidel：依序更新，立即使用新分量
A = [4 1;2 3]; % 嚴格列對角優勢矩陣
b = [6;8]; % 真解為 [1;2]
% 檢查有限實數矩陣及向量
validateattributes(A, {'double'}, {'2d','real','finite','nonempty'});
validateattributes(b, {'double'}, {'vector','real','finite','nonempty'});
n = size(A,1); % 方程式數量
if size(A,2) ~= n || numel(b) ~= n
    error('Linear:Dimensions', '本程式只接受 n×n 方陣及 n 個常數。');
end
b = b(:); % 統一轉為直向向量
A0 = A; b0 = b; % 保留原題供殘差檢查
matrixScale = norm(A,inf); % 矩陣尺度
if ~isfinite(matrixScale) || matrixScale == 0
    error('Linear:Scale', '矩陣尺度無效或為零。');
end
if rcond(A) <= 1e-12
    error('Linear:Singular', '矩陣奇異或數值近奇異；本唯一解範例停止，不宣稱無解。');
end
pivotTol = 1e-12*matrixScale; % 相對矩陣尺度的保護門檻，不是精確秩判定

x0 = [0;0]; % 初始向量
tolerance = 1e-2; % 絕對殘差無窮範數容許值
maxIterations = 100; % 防止無限迴圈
validateattributes(x0, {'double'}, {'vector','real','finite','numel',n});
validateattributes(tolerance, {'double'}, {'scalar','real','finite','positive'});
validateattributes(maxIterations, {'double'}, {'scalar','integer','>=',1,'<=',10000});
if any(abs(diag(A)) <= pivotTol)
    error('GaussSeidel:Diagonal', '對角元素為零或相對過小，不能直接除法。');
end
if any(abs(diag(A)) <= sum(abs(A),2)-abs(diag(A)))
    warning('GaussSeidel:Convergence', '不是嚴格列對角優勢；須另外分析收斂，不保證成功。');
end
x = x0(:); % 統一向量方向
history = zeros(0,n+2); % k、各分量、殘差
residual = norm(b-A*x,inf); % 初始殘差
if ~isfinite(residual), error('GaussSeidel:NonFinite','初始殘差溢位。'); end
converged = residual <= tolerance; % 初始值達標可為零次迭代
for k = 1:maxIterations
    if converged, break; end % 先檢查初始成功
    xOld = x; % 保存尚未更新分量所需的上一輪值
    for i = 1:n
        lower = A(i,1:i-1)*x(1:i-1); % j<i 使用本輪新值
        upper = A(i,i+1:n)*xOld(i+1:n); % j>i 使用上一輪舊值
        x(i) = (b(i)-lower-upper)/A(i,i); % 更新第 i 分量
    end
    residual = norm(b-A*x,inf); % 每完成整輪才計算殘差
    if any(~isfinite(x)) || ~isfinite(residual)
        error('GaussSeidel:NonFinite', '迭代產生非有限值。');
    end
    history(end+1,:) = [k,x.',residual]; % 保存可核對的逐輪結果
    fprintf('%d: ',k); fprintf('%.12g ',x); fprintf('殘差 %.12e\n',residual);
    converged = residual <= tolerance; % 主要停止條件，不是步長
    if ~converged && isequal(x,xOld)
        error('GaussSeidel:Precision', '浮點停滯且殘差未達標。');
    end
end
if ~converged
    error('GaussSeidel:MaxIterations', '已達最大迭代次數，尚未收斂。');
end
disp(x); % 顯示達到殘差條件的近似解，不宣稱為精確解
